import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  experimental: {
    dynamicIO: true,
  },
};

export default nextConfig;

import { revalidateTag } from "next/cache";
import { getAllProducts } from "@/lib/db";

export default function Page() {
  return (
    <div style={{ padding: "2rem" }}>
      <h1>Product Listing</h1>
      <ProductList />

      <form
        style={{ marginTop: "2rem", padding: "1rem", border: "1px solid #ccc" }}
      >
        <h2>Cache Management</h2>
        <p>Last cache update: {new Date().toLocaleString()}</p>
        <button
          formAction={async () => {
            "use server";
            revalidateTag("products");
          }}
          style={{
            padding: "0.5rem 1rem",
            backgroundColor: "#0070f3",
            color: "white",
            border: "none",
            borderRadius: "4px",
            cursor: "pointer",
          }}
        >
          Refresh Products Cache
        </button>
        <p style={{ fontSize: "0.875rem", color: "#666", marginTop: "0.5rem" }}>
          Clicking this button will invalidate the products cache and trigger a fresh fetch.
        </p>
      </form>
    </div>
  );
}

async function ProductList() {
  "use cache";

  const products = await getAllProducts();

  return (
    <div>
      <p style={{ color: "#666", marginBottom: "1rem" }}>
        <em>Data cached with tag: &quot;products&quot;</em>
      </p>
      <ul style={{ listStyle: "none", padding: 0 }}>
        {products.map((product) => (
          <li
            key={product.id}
            style={{
              padding: "1rem",
              marginBottom: "0.5rem",
              border: "1px solid #eaeaea",
              borderRadius: "8px",
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
            }}
          >
            <span style={{ fontWeight: 600 }}>{product.name}</span>
            <span style={{ color: "#0070f3", fontWeight: 600 }}>
              ${product.price}
            </span>
          </li>
        ))}
      </ul>
    </div>
  );
}

import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  experimental: {
    dynamicIO: true,
  },
};

export default nextConfig;

import { revalidateTag, unstable_cacheLife as cacheLife } from "next/cache";
import { getAllProducts } from "@/lib/db";

export default function Page() {
  return (
    <div style={{ padding: "2rem" }}>
      <h1>Product Listing</h1>
      <ProductList />

      <CacheManagementForm />
    </div>
  );
}

async function ProductList() {
  "use cache";

  cacheLife("products");

  const products = await getAllProducts();

  return (
    <div>
      <p style={{ color: "#666", marginBottom: "1rem" }}>
        <em>Data cached with tag: &quot;products&quot;</em>
      </p>
      <ul style={{ listStyle: "none", padding: 0 }}>
        {products.map((product) => (
          <li
            key={product.id}
            style={{
              padding: "1rem",
              marginBottom: "0.5rem",
              border: "1px solid #eaeaea",
              borderRadius: "8px",
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
            }}
          >
            <span style={{ fontWeight: 600 }}>{product.name}</span>
            <span style={{ color: "#0070f3", fontWeight: 600 }}>
              ${product.price}
            </span>
          </li>
        ))}
      </ul>
    </div>
  );
}

function CacheManagementForm() {
  return (
    <form
      action={invalidateProductsCache}
      style={{ marginTop: "2rem", padding: "1rem", border: "1px solid #ccc" }}
    >
      <h2>Cache Management</h2>
      <p>Submit the form to invalidate the products cache and trigger a fresh data fetch.</p>
      <button
        type="submit"
        style={{
          padding: "0.5rem 1rem",
          backgroundColor: "#0070f3",
          color: "white",
          border: "none",
          borderRadius: "4px",
          cursor: "pointer",
        }}
      >
        Refresh Products Cache
      </button>
      <p style={{ fontSize: "0.875rem", color: "#666", marginTop: "0.5rem" }}>
        This uses revalidateTag(&quot;products&quot;) for selective invalidation.
      </p>
    </form>
  );
}

async function invalidateProductsCache() {
  "use server";
  revalidateTag("products");
}

